<template><div class="app-page"><div class="app-heading"><div><p class="eyebrow">PROJECT ARCHIVE / {{ projects.length }} ITEMS</p><h2>Project <em>files.</em></h2></div><div class="filter-row"><button v-for="item in filters" :key="item" :class="{ selected: filter === item }" @click="filter = item">{{ item }}</button></div></div><div class="project-grid"><article v-for="project in filteredProjects" :key="project.id" class="project-file"><img :src="project.image" :alt="project.title" loading="lazy"><div><p class="file-type">{{ project.category }} / {{ String(project.id).padStart(2, '0') }}</p><h3>{{ project.title }}</h3><p>{{ project.description }}</p><div class="chips"><span v-for="tech in project.techStack.slice(0, 4)" :key="tech">{{ tech }}</span></div><a :href="project.github" target="_blank" rel="noreferrer">Open repository ↗</a></div></article></div></div></template>
<script setup>import { computed, ref } from 'vue'; import { projects } from '@/data/projects'; const filters = ['All', 'Full-Stack', 'Backend', 'Frontend']; const filter = ref('All'); const filteredProjects = computed(() => filter.value === 'All' ? projects : projects.filter((project) => project.category === filter.value));</script>
